import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';import {videoMigration} from '../../tools/academy-session-video-migration.mjs';
import {world,signIn} from './academy-v111-native-fixture.mjs';
import {academyDraftGuard} from '../../../security/v2/academy-native-resources.mjs';
import {b64u,bytes,canonical} from '../../../security/v2/codec.mjs';
const origin='https://ummabbadacademy.app',headers={'X-Academy-Workspace':'ADMIN'};
export async function setup(){let rawAdmin;const f=await world({prepareAcademy:(raw,admin)=>{rawAdmin=admin;admin.exec('BEGIN IMMEDIATE;'+videoMigration(admin.prepare("SELECT type,name,sql FROM sqlite_master WHERE tbl_name='lesson_media_assets'").all())+'COMMIT;');assert.deepEqual(admin.prepare('PRAGMA foreign_key_check').all(),[]);raw.exec('BEGIN IMMEDIATE;'+videoMigration(raw.prepare("SELECT type,name,sql FROM sqlite_master WHERE tbl_name='lesson_media_assets'").all())+'COMMIT;');assert.deepEqual(raw.prepare('PRAGMA foreign_key_check').all(),[]);raw.exec(readFileSync(new URL('../../migrations/academy-core/0020_recording_companions.sql',import.meta.url),'utf8').replace(/CREATE (TABLE|INDEX) (?!IF NOT EXISTS)/g,'CREATE $1 IF NOT EXISTS '));raw.exec(readFileSync(new URL('../../migrations/academy-core/0023_media_playlists.sql',import.meta.url),'utf8').replace(/CREATE (TABLE|INDEX|UNIQUE INDEX|TRIGGER) (?!IF NOT EXISTS)/g,'CREATE $1 IF NOT EXISTS '));}});f.envs.academy.ACADEMY_ACCEPTED_SETUP='1';f.envs.academy.ACADEMY_MEDIA_SEPARATION='1';f.loginId='separation-global';let login=await signIn(f);const cap=await f.runtimes.academy.authorise(new Request(origin+'/api/account/session',{headers:{Origin:origin,Cookie:f.jar.header(origin),'X-UAA-Request':'2','X-UAA-Expected-Context':b64u(bytes(canonical(login.context)))}}),{action:'read'});const activityKey=f.databases.academy.prepare("SELECT activity_key FROM activities WHERE kind='PROGRAM' AND active=1 LIMIT 1").get().activity_key;const refresh=async()=>{const boot=await f.post('academy','/auth/v2/bootstrap',{purpose:'refresh',expectedContext:login.context}),renewed=await f.post('academy','/auth/v2/refresh',{operationId:boot.data.intent.id,expectedContext:login.context,qualifyingActivity:true},boot.data);assert.equal(renewed.response.status,200,JSON.stringify(renewed.data));Object.assign(login,renewed.data);};const send=async(path,body)=>{if(!/[/](options|get|binding-options|comments)$/.test(path)&&f.databases.academy.prepare('SELECT authority_ready FROM jwt_v2_families WHERE sid=?').get(login.context.sid)?.authority_ready===0)await refresh();return f.nativeRequest('/api/academy/'+path,{activityKey,...body},login,{headers});};const guard=resource=>academyDraftGuard({runtime:f.runtimes.academy,cap,store:f.runtimes.academy.store,env:f.envs.academy,binding:cap.binding,rights:cap.rights,resource});return {...f,rawAdmin,login,cap,activityKey,send,guard,refresh};}
export async function playlist(f){let read=await f.send('media-playlists/options',{});assert.equal(read.response.status,200,JSON.stringify({data:read.data,error:read.nativeError?.message}));const classId=read.data.classes[0].id;read=await f.send('media-playlists/options',{classId});assert.equal(read.response.status,200,JSON.stringify(read.data));const id=crypto.randomUUID(),data=read.data;assert(data.subjects.length);const body={operationId:crypto.randomUUID(),playlistId:id,revision:data.revision,playlistRevision:0,name:'Native selected Program media',closeDate:'',classId,subjectKey:data.subjects[0].key,teacherIds:[],optionsRevision:data.optionsRevision};return {id,body};}
